final class ActiveQueue {
    private let q = DispatchQueue(label: "mq")          // scheduler + queue
    private var state: [Message] = []
    func put(_ m: Message, done: @escaping () -> Void = {}) {
        q.async { self.state.append(m); done() }         // serialized
    }
    func get(_ result: @escaping (Message?) -> Void) {
        q.async { result(self.state.isEmpty ? nil : self.state.removeFirst()) }
    }
}
